 * independent piece of state per key, created the first time that key
 * reaches them, and both expose the same three-step protocol the
 * simulator drives: `advance(key, tick)`, `allows(key)`, `record(key)`.
 */

/**
 * A token bucket. Tokens are tracked as an exact fraction with a fixed
 * denominator of `per`, so refills across many small ticks never lose
 * precision to floating point: after `n` ticks the bucket holds exactly
 * `refill * n` more "per-scaled" tokens than it did, capped at
 * `capacity * per`.
 */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.capacityScaled = capacity * per
    this.states = new Map()
  }

  #stateFor(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { scaled: this.capacityScaled, lastTick: tick }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#stateFor(key, tick)
    const delta = tick - state.lastTick
    if (delta > 0n) {
      const grown = state.scaled + this.refill * delta
      state.scaled = grown > this.capacityScaled ? this.capacityScaled : grown
      state.lastTick = tick
    }
  }

  allows(key) {
    const state = this.states.get(key)
    return state.scaled >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.scaled -= this.per
  }
}

/**
 * A sliding window. Remembers the ticks of the requests it recorded for
 * each key, oldest first, so forgetting ticks at or before the cutoff is
 * a simple pop from the front.
 */
export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #stateFor(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { ticks: [] }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#stateFor(key)
    const cutoff = tick - this.span
    let drop = 0
    while (drop < state.ticks.length && state.ticks[drop] <= cutoff) drop++
    if (drop > 0) state.ticks.splice(0, drop)
  }

  allows(key) {
    const state = this.states.get(key)
    return BigInt(state.ticks.length) < this.limit
  }

  record(key) {
    const state = this.states.get(key)
    state.ticks.push(this.#currentTick)
  }
}
