 * Parses a limiter file and replays its events. `simulate` is the single
 * entry point: it validates the whole file first (throwing a
 * `LimiterError` at the first problem, per the spec's "stop at the
 * first" rule) and, once the file parses, returns every event's verdict
 * in log order for the two output modes to format.
 */
import { LimiterError } from './errors.js'
import { TokenBucket, SlidingWindow } from './policies.js'

const IDENT = /^[A-Za-z0-9_./:-]+$/
const INTEGER = /^(0|[1-9][0-9]*)$/

/** Splits the raw limiter file into its lines, dropping only the empty
 * tail a trailing newline produces. */
function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

export function simulate(text) {
  const lines = splitLines(text)
  const policies = new Map()
  const routes = new Map()
  let eventSeen = false
  let lastTick = null

  const events = []
  const tally = new Map()
  let totalAllowed = 0
  let totalDenied = 0

  const fail = (lineNo, reason) => {
    throw new LimiterError(lineNo, reason)
  }

  const parseCount = (lineNo, str, field, least) => {
    if (!INTEGER.test(str)) fail(lineNo, `${field} must be an integer of at least ${least}`)
    const value = BigInt(str)
    if (value < least) fail(lineNo, `${field} must be an integer of at least ${least}`)
    return value
  }

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]
    const rest = tokens.slice(1)

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (eventSeen) fail(lineNo, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (rest.length !== 4) fail(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      const [name, capacityStr, refillStr, perStr] = rest
      if (!IDENT.test(name)) fail(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      const capacity = parseCount(lineNo, capacityStr, 'capacity', 1n)
      const refill = parseCount(lineNo, refillStr, 'refill', 0n)
      const per = parseCount(lineNo, perStr, 'per', 1n)
      policies.set(name, new TokenBucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (rest.length !== 3) fail(lineNo, 'expected window <name> <limit> <span>')
      const [name, limitStr, spanStr] = rest
      if (!IDENT.test(name)) fail(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      const limit = parseCount(lineNo, limitStr, 'limit', 0n)
      const span = parseCount(lineNo, spanStr, 'span', 1n)
      policies.set(name, new SlidingWindow(limit, span))
    } else if (directive === 'route') {
      if (rest.length < 2) fail(lineNo, 'expected route <prefix> <policy>...')
      const [prefix, ...policyNames] = rest
      if (!IDENT.test(prefix)) fail(lineNo, `invalid route prefix ${prefix}`)
      if (routes.has(prefix)) fail(lineNo, `prefix ${prefix} is routed twice`)
      for (const pname of policyNames) {
        if (!policies.has(pname)) fail(lineNo, `unknown policy ${pname}`)
      }
      routes.set(prefix, policyNames)
    } else if (directive === 'event') {
      if (rest.length !== 2) fail(lineNo, 'expected event <tick> <key>')
      const [tickStr, keyStr] = rest
      const tick = parseCount(lineNo, tickStr, 'tick', 0n)
      if (!IDENT.test(keyStr)) fail(lineNo, `invalid key ${keyStr}`)
      if (lastTick !== null && tick < lastTick) fail(lineNo, `tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      eventSeen = true

      let matchedPrefix = null
      let matchedNames = []
      for (const [prefix, names] of routes) {
        if (keyStr.startsWith(prefix) && (matchedPrefix === null || prefix.length > matchedPrefix.length)) {
          matchedPrefix = prefix
          matchedNames = names
        }
      }

      for (const pname of matchedNames) policies.get(pname).advance(keyStr, tick)

      let denyPolicy = null
      for (const pname of matchedNames) {
        if (!policies.get(pname).allows(keyStr)) {
          denyPolicy = pname
          break
        }
      }
      const allowed = denyPolicy === null
      if (allowed) for (const pname of matchedNames) policies.get(pname).record(keyStr, tick)

      events.push({ tick, key: keyStr, allowed, denyPolicy })

      let entry = tally.get(keyStr)
      if (entry === undefined) {
        entry = { allowed: 0, denied: 0 }
        tally.set(keyStr, entry)
      }
      if (allowed) {
        entry.allowed++
        totalAllowed++
      } else {
        entry.denied++
        totalDenied++
      }
    } else {
      fail(lineNo, `unknown directive ${directive}`)
    }
  }

  return { events, tally, totalAllowed, totalDenied }
}
"}

