 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'
import { simulate } from './simulate.js'
import { LimiterError } from './errors.js'

const mode = process.argv[2]
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const input = readFileSync(0, 'utf8')

let result
try {
  result = simulate(input)
} catch (err) {
  if (err instanceof LimiterError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(2)
  }
  throw err
}

let output = ''
if (mode === 'replay') {
  for (const event of result.events) {
    output += event.allowed
      ? `${event.tick} ${event.key} allow\n`
      : `${event.tick} ${event.key} deny ${event.denyPolicy}\n`
  }
} else {
  const keys = [...result.tally.keys()].sort()
  for (const key of keys) {
    const entry = result.tally.get(key)
    output += `${key} allowed=${entry.allowed} denied=${entry.denied}\n`
  }
  output += `total allowed=${result.totalAllowed} denied=${result.totalDenied}\n`
}

process.stdout.write(output)
process.exit(0)
"}

